// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount) public {
        address caller = address(0x1234);
        vm.assume(cashOutAmount > 0);
        vm.assume(depositAmount < 1 ether);
        vm.assume(cashOutAmount <= depositAmount + 1);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();
        uint256 totalBalBefore = c.balances(caller);
        uint256 contractBalBefore = address(c).balance;
        uint256 totalBefore = totalBalBefore + contractBalBefore;
        vm.prank(caller);
        try c.CashOut(cashOutAmount) {} catch {}
        uint256 totalBalAfter = c.balances(caller);
        uint256 contractBalAfter = address(c).balance;
        uint256 totalAfter = totalBalAfter + contractBalAfter;
        assertTrue(totalAfter >= totalBefore);
    }
}
